-- Tercer usuario (docs/especificacion-tercer-usuario.md): cada página
-- tiene un dueño. Vacío = de Alejandro y David; 'wilson' = de Wilson.
-- Lo que Wilson ve y puede tocar se decide por esta columna.
--
-- También carga la página de Jordan Hurtado con su identidad de tuit
-- (la foto está recortada de la captura de su tuit). Se puede correr
-- más de una vez: si la página ya existe, solo la actualiza.

alter table paginas
  add column if not exists asignada_a text;

insert into paginas (nombre, visible, nombre_tuit, usuario_tuit, avatar_url, asignada_a)
values (
  'Jordan Hurtado',
  true,
  'Jordan Hurtado',
  '@JordanHurtad0',
  'data:image/jpeg;base64,',
  'wilson'
)
on conflict (nombre) do update set
  nombre_tuit = excluded.nombre_tuit,
  usuario_tuit = excluded.usuario_tuit,
  avatar_url = excluded.avatar_url,
  asignada_a = excluded.asignada_a;
